export const PATCHED_SHA256 = "39d21f44811c6e335561d91982ab3403f1407348b5bdc14d0d2a14beb0eff9b7";

const SPEC_KEYS = "windSpeed,windDir,fetchKm,swellHs,swellLength,swellDir,swellSpread,choppy";

